import random

from dsu import DSU


class NaiveOracle:
    """Label-propagation reference: components tracked by explicit relabeling."""

    def __init__(self, n):
        self.label = list(range(n))

    def union(self, a, b):
        ra, rb = self.label[a], self.label[b]
        if ra == rb:
            return False
        for i, l in enumerate(self.label):
            if l == rb:
                self.label[i] = ra
        return True

    def connected(self, a, b):
        return self.label[a] == self.label[b]


def test_union_links_roots_not_elements():
    # union(0, 1), then union(2, 1): the second union must still leave 0~1.
    dsu = DSU(3)
    assert dsu.union(0, 1) is True
    assert dsu.union(2, 1) is True
    assert dsu.connected(0, 1), "0 and 1 were merged but now report disconnected"


def test_fuzz_against_oracle():
    rng = random.Random(42)
    n = 200
    dsu = DSU(n)
    oracle = NaiveOracle(n)

    for op in range(1, 2001):
        a, b = rng.randrange(n), rng.randrange(n)
        assert dsu.union(a, b) == oracle.union(a, b), f"union return mismatch at op {op}"
        if op % 100 == 0:
            for _ in range(50):
                x, y = rng.randrange(n), rng.randrange(n)
                assert dsu.connected(x, y) == oracle.connected(x, y), (
                    f"connected({x}, {y}) disagrees with oracle after {op} ops"
                )

